package com.google.gson;

import java.lang.reflect.Field;
import java.util.Locale;

/**
 * An enumeration that defines a few standard naming conventions for JSON field names.
 * This enumeration should be used in conjunction with {@link com.google.gson.GsonBuilder}
 * to configure a {@link com.google.gson.Gson} instance to properly translate Java field
 * names into the desired JSON field names.
 *
 * @author Inderjeet Singh
 * @author Joel Leitch
 */
public enum FieldNamingPolicy implements FieldNamingStrategy {

  /**
   * Using this naming policy with Gson will ensure that the field name is
   * unchanged.
   */
  IDENTITY(false, '\0', false, false, false),

  /**
   * Using this naming policy with Gson will ensure that the first "letter" of the Java
   * field name is capitalized when serialized to its JSON form.
   *
   * <p>Here's a few examples of the form "Java Field Name" ---&gt; "JSON Field Name":</p>
   * <ul>
   *   <li>someFieldName ---&gt; SomeFieldName</li>
   *   <li>_someFieldName ---&gt; _SomeFieldName</li>
   * </ul>
   */
  UPPER_CAMEL_CASE(false, '\0', true, false, false),

  /**
   * Using this naming policy with Gson will ensure that the first "letter" of the Java
   * field name is capitalized when serialized to its JSON form and the words will be
   * separated by a space.
   *
   * <p>Here's a few examples of the form "Java Field Name" ---&gt; "JSON Field Name":</p>
   * <ul>
   *   <li>someFieldName ---&gt; Some Field Name</li>
   *   <li>_someFieldName ---&gt; _Some Field Name</li>
   * </ul>
   *
   * @since 1.4
   */
  UPPER_CAMEL_CASE_WITH_SPACES(true, ' ', true, false, false),

  /**
   * Using this naming policy with Gson will modify the Java Field name from its camel cased
   * form to a lower case field name where each word is separated by an underscore (_).
   *
   * <p>Here's a few examples of the form "Java Field Name" ---&gt; "JSON Field Name":</p>
   * <ul>
   *   <li>someFieldName ---&gt; some_field_name</li>
   *   <li>_someFieldName ---&gt; _some_field_name</li>
   *   <li>aStringField ---&gt; a_string_field</li>
   *   <li>aURL ---&gt; a_u_r_l</li>
   * </ul>
   */
  LOWER_CASE_WITH_UNDERSCORES(true, '_', false, true, false),

  /**
   * Using this naming policy with Gson will modify the Java Field name from its camel cased
   * form to a lower case field name where each word is separated by a dash (-).
   *
   * <p>Here's a few examples of the form "Java Field Name" ---&gt; "JSON Field Name":</p>
   * <ul>
   *   <li>someFieldName ---&gt; some-field-name</li>
   *   <li>_someFieldName ---&gt; _some-field-name</li>
   *   <li>aStringField ---&gt; a-string-field</li>
   *   <li>aURL ---&gt; a-u-r-l</li>
   * </ul>
   * Using dashes in JavaScript is not recommended since dash is also used for a minus sign in
   * expressions. This requires that a field named with dashes is always accessed as a quoted
   * property like {@code myobject['my-field']}. Accessing it as an object field
   * {@code myobject.my-field} will result in an unintended javascript expression.
   * @since 1.4
   */
  LOWER_CASE_WITH_DASHES(true, '-', false, true, false),

  /**
   * Using this naming policy with Gson will modify the Java Field name from its camel cased
   * form to a lower case field name where each word is separated by a dot (.).
   *
   * <p>Here's a few examples of the form "Java Field Name" ---&gt; "JSON Field Name":</p>
   * <ul>
   *   <li>someFieldName ---&gt; some.field.name</li>
   *   <li>_someFieldName ---&gt; _some.field.name</li>
   *   <li>aStringField ---&gt; a.string.field</li>
   *   <li>aURL ---&gt; a.u.r.l</li>
   * </ul>
   * Using dots in JavaScript is not recommended since dot is also used for a member sign in
   * expressions. This requires that a field named with dots is always accessed as a quoted
   * property like {@code myobject['my.field']}. Accessing it as an object field
   * {@code myobject.my.field} will result in an unintended javascript expression.
   * @since 2.8
   */
  LOWER_CASE_WITH_DOTS(true, '.', false, true, false);

  private final boolean separateCamelCaseWords;
  private final char wordSeparator;
  private final boolean capitalizeFirstLetter;
  private final boolean convertToLowerCase;
  private final boolean convertToUpperCase;

  FieldNamingPolicy(
      boolean separateCamelCaseWords,
      char wordSeparator,
      boolean capitalizeFirstLetter,
      boolean convertToLowerCase,
      boolean convertToUpperCase) {
    this.separateCamelCaseWords = separateCamelCaseWords;
    this.wordSeparator = wordSeparator;
    this.capitalizeFirstLetter = capitalizeFirstLetter;
    this.convertToLowerCase = convertToLowerCase;
    this.convertToUpperCase = convertToUpperCase;
  }

  /**
   * Translates the Java field name into the JSON field name required by this policy.
   * The conversion inspects field metadata, splits camel-case words, optionally
   * capitalizes the first letter and finally applies a locale-independent case change.
   */
  @Override
  public String translateName(Field field) {
    if (field == null) {
      throw new NullPointerException();
    }

    FieldAttributes attributes = new FieldAttributes(field);
    String originalName = attributes.getName();
    int originalLength = originalName.length();
    if (originalLength == 0) {
      return originalName;
    }

    boolean shouldSeparateWords = separateCamelCaseWords;
    boolean shouldCapitalizeFirstLetter = capitalizeFirstLetter;
    boolean shouldConvertToLowerCase = convertToLowerCase;
    boolean shouldConvertToUpperCase = convertToUpperCase;
    char separator = wordSeparator;

    String translatedName;
    if (shouldSeparateWords) {
      StringBuilder translation = new StringBuilder(originalLength + 8);
      for (int index = 0; index < originalLength; index++) {
        char character = originalName.charAt(index);
        boolean uppercaseLetter = Character.isUpperCase(character);
        if (uppercaseLetter) {
          int translatedLength = translation.length();
          if (translatedLength != 0) {
            translation.append(separator);
          }
          translation.append(character);
        } else {
          translation.append(character);
        }
      }
      translatedName = translation.toString();
    } else {
      translatedName = originalName;
    }

    if (shouldCapitalizeFirstLetter) {
      int translatedLength = translatedName.length();
      for (int index = 0; index < translatedLength; index++) {
        char current = translatedName.charAt(index);
        if (Character.isLetter(current)) {
          boolean alreadyUppercase = Character.isUpperCase(current);
          if (alreadyUppercase) {
            break;
          }

          char uppercased = Character.toUpperCase(current);
          boolean firstCharacter = index == 0;
          boolean lastCharacter = index + 1 >= translatedLength;
          if (firstCharacter && lastCharacter) {
            translatedName = String.valueOf(uppercased);
          } else if (firstCharacter) {
            String remaining = translatedName.substring(1);
            translatedName = uppercased + remaining;
          } else if (lastCharacter) {
            String prefix = translatedName.substring(0, index);
            translatedName = prefix + uppercased;
          } else {
            String prefix = translatedName.substring(0, index);
            String suffix = translatedName.substring(index + 1);
            translatedName = prefix + uppercased + suffix;
          }
          break;
        }
      }
    }

    if (shouldConvertToLowerCase) {
      return translatedName.toLowerCase(Locale.ENGLISH);
    }
    if (shouldConvertToUpperCase) {
      return translatedName.toUpperCase(Locale.ENGLISH);
    }
    return translatedName;
  }

  /**
   * Converts the field name that uses camel-case define word separation into
   * separate words that are separated by the provided {@code separator}.
   */
  static String separateCamelCase(String name, char separator) {
    StringBuilder translation = new StringBuilder();
    for (int i = 0, length = name.length(); i < length; i++) {
      char character = name.charAt(i);
      if (Character.isUpperCase(character) && translation.length() != 0) {
        translation.append(separator);
      }
      translation.append(character);
    }
    return translation.toString();
  }

  /**
   * Ensures the JSON field names begins with an upper case letter.
   */
  static String upperCaseFirstLetter(String s) {
    int length = s.length();
    for (int i = 0; i < length; i++) {
      char c = s.charAt(i);
      if (Character.isLetter(c)) {
        if (Character.isUpperCase(c)) {
          return s;
        }

        char uppercased = Character.toUpperCase(c);
        // For leading letter only need one substring
        if (i == 0) {
          return uppercased + s.substring(1);
        } else {
          return s.substring(0, i) + uppercased + s.substring(i + 1);
        }
      }
    }

    return s;
  }
}

